import heapq

def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None
    explored = set()
    shortest_paths = {start: (None, 0)}
    distance = {start: 0}
    pq = [(0, start)]
    while len(pq) > 0:
        cost_so_far, current_node = heapq.heappop(pq)
        if current_node == goal:
            print('A star path found:', [k for k, _ in shortest_paths[goal]])
            result = []
            current_node = goal
            while current_node != start:
                path, cost = shortest_paths[current_node]
                result.append(path)
                current_node = path
            return reverse_order(result)
        explored.add(current_node)
        for next in graph[current_node]:
            if next in explored:
                continue
            next_cost = cost_so_far + graph[current_node][next].get('cost', 1)
            if next not in shortest_paths or next_cost < distance[next]:
                shortest_paths[next] = (current_node, next_cost)
                distance[next] = next_cost
                heapq.heappush(pq, (next_cost, next))
    return None

def reverse_order(lst):
    return lst[::-1] if lst else []

