def find_path_dijkstra(graph, start, goal):
    """Find a shortest path between start node to goal node using Dijkstra's algorithm (unweighted graph assumption)."""
    if start == goal:
        return [start]

    path_found = False
    path = []
    # Keep a track of already discovered nodes and distances to it
    discovered = {node: float('infinity') for node in graph}
    discovered[start] = 0

    # Priority queue (queue of pairs (distance, node index in graph))
    pq = Queue()
    # (distance_to_node, index_in_dict, index_in_graph)
    pq.put((0, 0, start))

    predecessors = {node: None for node in graph}

    while not path_found and not pq.empty():
        _, _, node = pq.get()
        path.append(node)
        for neighbor in graph[node]:
            distance = discovered[node] + 1
            if distance < discovered[neighbor]:
                pq.put((distance, graph[neighbor].index(neighbor), neighbor))
                discovered[neighbor] = distance
                predecessors[neighbor] = node
        if node == goal:
            path_found=True

    return [goal] + path[:path.index(goal)+1] if path_found else None

