import heapq

def find_path_dijkstra(graph, start, goal):

    def dijkstra_path(graph, start, goal):
        priority_queue = [(0, start)]
        visited = {node: None for node in graph}
        cost = {node: float('inf') for node in graph}
        cost[start] = 0
        while priority_queue:
            current_cost, current_node = heapq.heappop(priority_queue)
            if current_node == goal:
                path = []
                while current_node is not None:
                    path.append(current_node)
                    current_node = visited[current_node]
                return path
            for next_node in graph[current_node]:
                temp_cost = current_cost + graph[current_node][next_node]
                if temp_cost < cost[next_node]:
                    cost[next_node] = temp_cost
                    previous_node = current_node
                    visited[next_node] = previous_node
                    heapq.heappush(priority_queue, (temp_cost, next_node))
        return None
    return dijkstra_path(graph, start, goal)

