def find_path(graph, start, goal):
    explored = set()
    stack = [[start]]
    if start == goal:
        return [start]
    while stack:
        path = stack.pop()
        node = path[-1]
        if node not in explored:
            neighbours = graph.get(node)
            if neighbours:
                next_steps = [step for step in neighbours if step not in explored]
                next_paths = [path + [next_step] for next_step in next_steps]
                stack.extend(next_paths)
                if goal in next_steps:
                    return path + [goal]
            explored.add(node)
    return None
